from dataclasses import dataclass


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: 'Expr'
    r: 'Expr'


@dataclass
class Mul:
    l: 'Expr'
    r: 'Expr'


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an expression tree: Num yields its value, Add sums the
    evaluated children, and Mul multiplies the evaluated children."""
    match e:
        case Num(v=v):
            return v
        case Add(l=l, r=r):
            return eval_expr(l) + eval_expr(r)
        case Mul(l=l, r=r):
            return eval_expr(l) * eval_expr(r)


def test_num() -> None:
    assert eval_expr(Num(5)) == 5
    assert eval_expr(Num(0)) == 0
    assert eval_expr(Num(-3)) == -3


def test_add() -> None:
    assert eval_expr(Add(Num(2), Num(3))) == 5
    assert eval_expr(Add(Num(-2), Num(2))) == 0


def test_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(3))) == 12
    assert eval_expr(Mul(Num(-4), Num(3))) == -12
    assert eval_expr(Mul(Num(0), Num(99))) == 0


def test_nested() -> None:
    # (2 + 3) * 4 == 20
    assert eval_expr(Mul(Add(Num(2), Num(3)), Num(4))) == 20
    # 2 + (3 * 4) == 14
    assert eval_expr(Add(Num(2), Mul(Num(3), Num(4)))) == 14
    # (1 + 2) * (3 + 4) == 21
    assert eval_expr(Mul(Add(Num(1), Num(2)), Add(Num(3), Num(4)))) == 21


def test_operand_order_and_identity() -> None:
    # Mul by one and Add of zero are identities on either side.
    assert eval_expr(Mul(Num(1), Num(7))) == 7
    assert eval_expr(Mul(Num(7), Num(1))) == 7
    assert eval_expr(Add(Num(0), Num(7))) == 7
    assert eval_expr(Add(Num(7), Num(0))) == 7


def test_deep_chain() -> None:
    e: Expr = Num(0)
    for i in range(1, 101):
        e = Add(e, Num(i))
    assert eval_expr(e) == 5050


def test_large_values() -> None:
    big = 10**18
    assert eval_expr(Mul(Num(big), Num(big))) == big * big

